# Run from the package root after 55_area_basis.R:  Rscript data-raw/qa/55b_area_basis_tables.R     Saves data-raw/qa/out/area_basis_tables.rds
# Compares the two bases for the share of a ZCTA inside a path: intersection / ALAND (land only, the published basis, before the cap) and intersection / area of the full ZCTA polygon (land and water).
suppressMessages({library(dplyr)}); source("data-raw/qa/helpers.R"); A <- readRDS(qa_out("area_basis_pairs.rds")); options(width = 220)
a <- A %>% mutate(land = intersection_m2 / ALAND, full = intersection_m2 / zcta_poly_m2, water_share = AWATER / (ALAND + AWATER), poly_over_aland = zcta_poly_m2 / ALAND, year = as.integer(substr(tornado_id, 1, 4)))
R <- list(); R$rows <- nrow(a); R$poly_vs_aland_zcta <- a %>% distinct(vintage, ZCTA, .keep_all = TRUE) %>% group_by(vintage) %>% summarise(zctas = n(), median_polygon_over_ALAND = median(poly_over_aland), p90 = quantile(poly_over_aland, .9), max = max(poly_over_aland), zctas_with_water_over_10pct = sum(water_share > .1), zctas_with_water_over_50pct = sum(water_share > .5), .groups = "drop")
R$above1 <- a[a$land > 1, c("tornado_id", "ZCTA", "vintage", "track_type", "intersection_m2", "ALAND", "zcta_poly_m2", "AWATER", "land", "full")]
R$ratio_quant <- quantile(a$land / a$full, c(0, .01, .1, .5, .9, .99, .999, 1)); R$ratio_by_water <- a %>% mutate(water_class = cut(water_share, c(-Inf, 0.01, 0.1, 0.5, Inf), labels = c("water under 1%", "1-10%", "10-50%", "over 50%"))) %>% group_by(water_class) %>% summarise(rows = n(), median_land_over_full = median(land / full), p90 = quantile(land / full, .9), max = max(land / full), rows_land_basis_above_1 = sum(land > 1), median_full_basis = median(full), median_land_basis = median(land), .groups = "drop")
R$relative_difference_rows <- c(over_1pct = sum(a$land / a$full > 1.01), over_5pct = sum(a$land / a$full > 1.05), over_10pct = sum(a$land / a$full > 1.10), over_50pct = sum(a$land / a$full > 1.5))
th <- c(0.01, 0.05, 0.1, 0.5); R$threshold_effect <- do.call(rbind, lapply(th, function(t) data.frame(area_thresh = t, rows_land_basis = sum(pmin(a$land, 1) >= t), rows_full_basis = sum(a$full >= t), rows_only_in_land_basis = sum(pmin(a$land, 1) >= t & a$full < t), rows_only_in_full_basis = sum(a$land < t & a$full >= t))))
R$coast <- a %>% filter(water_share > 0.1) %>% summarise(rows = n(), tornadoes = n_distinct(tornado_id), zctas = n_distinct(paste(vintage, ZCTA)))
R$poly_over_aland_extremes <- head(a[order(-a$poly_over_aland), c("ZCTA", "vintage", "ALAND", "AWATER", "zcta_poly_m2", "poly_over_aland")] %>% distinct(ZCTA, vintage, .keep_all = TRUE), 10)
saveRDS(R, qa_out("area_basis_tables.rds")); for (n in names(R)) { cat("\n##", n, "\n"); print(R[[n]]) }
